"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["14464"],{73709(e){e.exports=JSON.parse('{"id":"V4-183","slug":"financial-conduct-authority","term":"Financial Conduct Authority (FCA)","also_known_as":[],"difficulty":"Intermediate","definition":"The Financial Conduct Authority (FCA) is the UK regulator responsible for the conduct of financial services firms and the integrity of financial markets, and for the prudential regulation of firms not supervised by the Prudential Regulation Authority.","explanation":["The FCA was created in 2013, when the Financial Services Authority was split into two bodies following the 2008 financial crisis. The FCA took over conduct regulation, while the Prudential Regulation Authority, part of the Bank of England, took over prudential supervision of banks, insurers and major investment firms.","The FCA\u2019s objectives are to protect consumers, protect and enhance the integrity of the UK financial system and promote effective competition in consumers\u2019 interests. It regulates tens of thousands of firms, including banks, insurers, investment firms, financial advisers, consumer credit firms and payment companies.","For example, the FCA introduced the Consumer Duty in 2023, requiring firms to deliver good outcomes for retail customers, and it has taken action on issues such as mis-sold payment protection insurance and motor finance commissions.","The FCA authorises firms, sets rules, supervises firms\u2019 conduct and takes enforcement action, including fines and bans. It is funded by fees paid by the firms it regulates and is accountable to Parliament through the Treasury."],"note":"","total":1725,"prev":{"slug":"financial-close","term":"Financial Close"},"next":{"slug":"financial-contagion","term":"Financial Contagion"}}')}}]);